import { useEffect, useRef, useState } from 'react';
import { Button, Stack, TextField, Toast } from '@jinx-ui/react';

export default function NewsletterSubscribeForm() {
  const [email, setEmail] = useState('');
  const [toastOpen, setToastOpen] = useState(false);
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    return () => {
      if (timerRef.current) clearTimeout(timerRef.current);
    };
  }, []);

  const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!email.trim()) return;

    setEmail('');
    setToastOpen(true);

    if (timerRef.current) clearTimeout(timerRef.current);
    timerRef.current = setTimeout(() => setToastOpen(false), 5000);
  };

  return (
    <form onSubmit={handleSubmit} style={{ maxWidth: 'var(--jx-size-form-width, 360px)' }}>
      <Stack direction="vertical" gap="var(--jx-space-3)">
        <TextField
          type="email"
          name="email"
          label="Почта"
          placeholder="you@example.com"
          value={email}
          required
          onChange={(event: React.ChangeEvent<HTMLInputElement>) => setEmail(event.target.value)}
        />
        <Button type="submit" variant="primary" disabled={!email.trim()}>
          Подписаться
        </Button>
      </Stack>

      <Toast
        open={toastOpen}
        placement="bottom-right"
        status="success"
        title="Готово"
        onClose={() => setToastOpen(false)}
      >
        Письмо с подтверждением отправлено на указанную почту.
      </Toast>
    </form>
  );
}

